PRAGMA foreign_keys = ON;
CREATE TABLE projects(id TEXT PRIMARY KEY, config TEXT NOT NULL CHECK(json_valid(config)));
CREATE TABLE oauth_states(hash TEXT PRIMARY KEY, browser_hash TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE TABLE links(project_id TEXT NOT NULL, discord_id TEXT NOT NULL, notion_id TEXT NOT NULL, verified_at INTEGER NOT NULL, valid_until INTEGER NOT NULL, PRIMARY KEY(project_id,discord_id), UNIQUE(project_id,notion_id));
CREATE TABLE challenges(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, user_id TEXT NOT NULL, session_hash TEXT NOT NULL, code_hash TEXT NOT NULL, created_at INTEGER NOT NULL, expires INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0, candidate TEXT, comment_id TEXT);
CREATE INDEX challenges_user ON challenges(project_id,user_id);
CREATE TABLE locks(id TEXT PRIMARY KEY, owner TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE drafts(id TEXT PRIMARY KEY, user_id TEXT NOT NULL, payload TEXT NOT NULL, expires INTEGER NOT NULL, submitted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'pending', next_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease TEXT, lease_until INTEGER, error TEXT, created_at INTEGER NOT NULL);
CREATE INDEX jobs_ready ON jobs(status,next_at,lease_until);
CREATE TABLE effects(id TEXT PRIMARY KEY, state TEXT NOT NULL, result TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE schedule_cursor(project_id TEXT PRIMARY KEY, next_week TEXT NOT NULL);
CREATE TABLE polls(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, week TEXT NOT NULL, opens INTEGER NOT NULL, closes INTEGER NOT NULL, members TEXT NOT NULL, message_id TEXT, thread_id TEXT, UNIQUE(project_id,week));
CREATE TABLE votes(poll_id TEXT NOT NULL REFERENCES polls(id), user_id TEXT NOT NULL, slots TEXT NOT NULL CHECK(json_valid(slots)), updated_at INTEGER NOT NULL, PRIMARY KEY(poll_id,user_id));
CREATE TABLE issue_links(page_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE, thread_id TEXT, message_id TEXT, last_edited TEXT, assignees TEXT NOT NULL DEFAULT '[]');
CREATE TABLE report_runs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, week TEXT NOT NULL, complete INTEGER NOT NULL DEFAULT 0, UNIQUE(project_id,week));
CREATE TABLE report_items(report_id TEXT NOT NULL REFERENCES report_runs(id), page_id TEXT NOT NULL, payload TEXT NOT NULL, due_sort TEXT NOT NULL, priority_rank INTEGER NOT NULL, created TEXT NOT NULL, PRIMARY KEY(report_id,page_id));
CREATE INDEX report_order ON report_items(report_id,due_sort,priority_rank,created,page_id);
CREATE TABLE webhook_events(id TEXT PRIMARY KEY, page_id TEXT NOT NULL, received_at INTEGER NOT NULL);
CREATE TABLE setup_secrets(id TEXT PRIMARY KEY, value TEXT NOT NULL, created_at INTEGER NOT NULL);
